from pathlib import Path

import click
from PIL import Image, ImageOps

EXTENSIONS = {".jpg", ".jpeg", ".png"}


def find_images(src: Path, recursive: bool) -> list[Path]:
    pattern = "**/*" if recursive else "*"
    return sorted(p for p in src.glob(pattern) if p.is_file() and p.suffix.lower() in EXTENSIONS)


@click.command()
@click.argument("src", type=click.Path(exists=True, file_okay=False, path_type=Path))
@click.argument("dst", type=click.Path(file_okay=False, path_type=Path))
@click.option("--width", type=click.IntRange(min=1), default=1280, show_default=True,
              help="Maximum width in pixels.")
@click.option("--quality", type=click.IntRange(1, 95), default=85, show_default=True,
              help="JPEG quality.")
@click.option("--overwrite", is_flag=True, help="Replace files that already exist in DST.")
@click.option("-r", "--recursive", is_flag=True,
              help="Also process subfolders (the folder structure is kept in DST).")
def shrink(src: Path, dst: Path, width: int, quality: int, overwrite: bool, recursive: bool) -> None:
    """Resize the images in SRC to at most WIDTH pixels wide and write them to DST."""
    images = find_images(src, recursive)
    if not images:
        raise click.ClickException(f"no images found in {src}")

    skipped = 0
    failed: list[tuple[Path, Exception]] = []
    with click.progressbar(images, label="Resizing",
                           item_show_func=lambda p: p.name if p else None) as bar:
        for path in bar:
            out = dst / path.relative_to(src)
            if out.exists() and not overwrite:
                skipped += 1
                continue
            out.parent.mkdir(parents=True, exist_ok=True)
            try:
                with Image.open(path) as img:
                    img = ImageOps.exif_transpose(img)
                    if img.width > width:
                        height = round(img.height * width / img.width)
                        img = img.resize((width, height), Image.Resampling.LANCZOS)
                    img.save(out, quality=quality, optimize=True)
            except OSError as e:
                failed.append((path, e))

    done = len(images) - skipped - len(failed)
    click.echo(f"{done} resized, {skipped} skipped (already exist)")
    for path, err in failed:
        click.secho(f"failed: {path}: {err}", fg="red", err=True)
    if failed:
        raise SystemExit(1)


if __name__ == "__main__":
    shrink()
```

What changed besides the switch to click:

- `click.Path(exists=True, file_okay=False)` rejects a missing or non-directory SRC with a proper usage error, and `path_type=Path` gives you `pathlib.Path` objects directly.
- `click.IntRange(1, 95)` validates quality; `--quality 120` now fails with `Error: Invalid value for '--quality': 120 is not in the range 1<=x<=95.`
- With `--recursive`, `dst / path.relative_to(src)` mirrors the subfolders, so two `IMG_0001.jpg` in different folders don't overwrite each other.
- `ImageOps.exif_transpose` applies the EXIF rotation; without it, phone photos taken in portrait often come out sideways after resizing.
- `LANCZOS` gives much sharper downscaling than the default filter.
- A broken image no longer stops the whole run; failures are listed at the end and the exit code is 1.

Install with `pip install click pillow`, then run e.g. `python shrink.py photos/ web/ -r --quality 80`.

Dataclasses give you the defaults and the schema in one place; a small builder walks them, applies env overrides and checks types.

```python
# config.py
from __future__ import annotations

import os
import tomllib
from dataclasses import dataclass, field, fields, is_dataclass
from pathlib import Path
from typing import Any, get_type_hints

LOG_LEVELS = {"DEBUG", "INFO", "WARNING", "ERROR", "CRITICAL"}


class ConfigError(Exception):
    pass


@dataclass
class ServerConfig:
    host: str = "127.0.0.1"
    port: int = 8000

    def __post_init__(self) -> None:
        if not 1 <= self.port <= 65535:
            raise ConfigError(f"server.port: {self.port} is not a valid port")


@dataclass
class DatabaseConfig:
    url: str = "sqlite:///app.db"
    pool_size: int = 5


@dataclass
class LoggingConfig:
    level: str = "INFO"

    def __post_init__(self) -> None:
        self.level = self.level.upper()
        if self.level not in LOG_LEVELS:
            raise ConfigError(f"logging.level: must be one of {sorted(LOG_LEVELS)}, got {self.level!r}")


@dataclass
class Config:
    server: ServerConfig = field(default_factory=ServerConfig)
    database: DatabaseConfig = field(default_factory=DatabaseConfig)
    logging: LoggingConfig = field(default_factory=LoggingConfig)


def _from_env(raw: str, typ: type, name: str) -> Any:
    if typ is bool:
        if raw.lower() in {"1", "true", "yes", "on"}:
            return True
        if raw.lower() in {"0", "false", "no", "off"}:
            return False
        raise ConfigError(f"{name}: expected a boolean, got {raw!r}")
    if typ in (int, float):
        try:
            return typ(raw)
        except ValueError:
            raise ConfigError(f"{name}: expected {typ.__name__}, got {raw!r}") from None
    return raw


def _check_type(value: Any, typ: type, where: str) -> Any:
    if typ is float and isinstance(value, int) and not isinstance(value, bool):
        return float(value)
    # bool is a subclass of int, so `port = true` would otherwise pass
    if not isinstance(value, typ) or (isinstance(value, bool) and typ is not bool):
        raise ConfigError(f"{where}: expected {typ.__name__}, got {type(value).__name__} ({value!r})")
    return value


def _build(cls: type, data: dict[str, Any], where: str, env_prefix: str) -> Any:
    hints = get_type_hints(cls)
    unknown = set(data) - {f.name for f in fields(cls)}
    if unknown:
        raise ConfigError(f"[{where or 'top level'}]: unknown key(s): {', '.join(sorted(unknown))}")

    kwargs: dict[str, Any] = {}
    for f in fields(cls):
        typ = hints[f.name]
        key = f"{where}.{f.name}" if where else f.name
        env_name = f"{env_prefix}_{f.name}".upper()
        if is_dataclass(typ):
            section = data.get(f.name, {})
            if not isinstance(section, dict):
                raise ConfigError(f"{key}: expected a table like [{key}]")
            kwargs[f.name] = _build(typ, section, key, env_name)
        elif env_name in os.environ:
            kwargs[f.name] = _from_env(os.environ[env_name], typ, env_name)
        elif f.name in data:
            kwargs[f.name] = _check_type(data[f.name], typ, key)
    return cls(**kwargs)


def load_config(path: str | Path = "config.toml", env_prefix: str = "APP") -> Config:
    path = Path(path)
    data: dict[str, Any] = {}
    if path.exists():
        try:
            with path.open("rb") as f:  # tomllib only accepts binary files
                data = tomllib.load(f)
        except tomllib.TOMLDecodeError as e:
            raise ConfigError(f"{path}: {e}") from None
    return _build(Config, data, "", env_prefix)
```

