from __future__ import annotations

from typing import Any


def flatten(obj: Any, sep: str = ".", prefix: str = "") -> dict[str, Any]:
    """{'db': {'host': 'x'}, 'servers': [{'name': 'a'}]} -> {'db.host': 'x', 'servers.0.name': 'a'}"""
    if isinstance(obj, dict):
        items = obj.items()
    elif isinstance(obj, list):
        items = enumerate(obj)
    else:
        return {prefix: obj}          # base case: a plain value

    if not obj and prefix:            # keep empty containers, otherwise they'd vanish
        return {prefix: type(obj)()}

    flat: dict[str, Any] = {}
    for key, value in items:
        key = str(key)
        if sep in key:
            raise ValueError(f"key {key!r} contains the separator {sep!r}")
        flat.update(flatten(value, sep, f"{prefix}{sep}{key}" if prefix else key))
    return flat


def unflatten(flat: dict[str, Any], sep: str = ".") -> Any:
    root: dict[str, Any] = {}
    for full_key, value in flat.items():
        *parents, last = full_key.split(sep)
        node = root
        for part in parents:
            node = node.setdefault(part, {})
            if not isinstance(node, dict):
                raise ValueError(f"{full_key!r} conflicts with a plain value at {part!r}")
        if last in node:
            raise ValueError(f"{full_key!r} conflicts with another key")
        node[last] = value
    return _restore_lists(root)


def _restore_lists(node: Any) -> Any:
    """Turn dicts whose keys are exactly '0', '1', ..., 'n-1' back into lists."""
    if not isinstance(node, dict):
        return node
    node = {k: _restore_lists(v) for k, v in node.items()}
    if node and set(node) == {str(i) for i in range(len(node))}:
        return [node[str(i)] for i in range(len(node))]
    return node
```

Round trip:

```python
>>> cfg = {
...     "db": {"host": "db.internal", "port": 5432},
...     "servers": [{"name": "web1", "tags": ["eu", "prod"]}, {"name": "web2", "tags": []}],
...     "debug": False,
... }
>>> flat = flatten(cfg)
>>> flat
{'db.host': 'db.internal', 'db.port': 5432, 'servers.0.name': 'web1', 'servers.0.tags.0': 'eu',
 'servers.0.tags.1': 'prod', 'servers.1.name': 'web2', 'servers.1.tags': [], 'debug': False}
>>> unflatten(flat) == cfg
True
```

For env-style files, use a separator that's valid in variable names and upper-case the keys:

```python
>>> {k.upper(): v for k, v in flatten(cfg, sep="__").items()}["SERVERS__0__NAME"]
'web1'
```

How the recursion works in `flatten`: each call handles one level. A dict or list calls `flatten` again for each child with a longer prefix; a plain value is the base case and returns a single entry. `_restore_lists` works bottom-up the same way: it fixes the children first, then decides whether the current dict is really a list.

Things to be aware of:

- **The round trip is lossless for JSON-like data, with one exception:** a dict with keys `"0"`, `"1"`, ... comes back as a list, because the flat form can't tell them apart.
- When you read values back from an env file, everything is a string (`"5432"`, `"False"`). Convert types afterwards, e.g. with `json.loads` on each value if you wrote them with `json.dumps`.
- `unflatten` raises on conflicts like `{"db": "x", "db.host": "y"}` instead of silently dropping one of them.
- Python's recursion limit (1000) is irrelevant for config files, but this isn't meant for arbitrarily deep data.

A few small validator classes that you combine into a schema. Each one checks its value and appends messages to a shared list instead of raising, so you get every problem in one pass.

```python
# manifest_schema.py
from __future__ import annotations

import json
import re
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any

_JSON_TYPES = {dict: "object", list: "array", str: "string", int: "integer",
               float: "number", bool: "boolean", type(None): "null"}


def _kind(value: Any) -> str:
    return _JSON_TYPES.get(type(value), type(value).__name__)


def _where(path: str) -> str:
    return path or "(root)"


class Validator:
    def check(self, value: Any, path: str, errors: list[str]) -> None:
        raise NotImplementedError


@dataclass
class Str(Validator):
    pattern: str | None = None
    min_len: int = 0
    max_len: int | None = None
    hint: str = ""  # shown when the pattern doesn't match

    def check(self, value: Any, path: str, errors: list[str]) -> None:
        if not isinstance(value, str):
            errors.append(f"{_where(path)}: expected string, got {_kind(value)}")
            return
        if len(value) < self.min_len:
            errors.append(f"{_where(path)}: must not be empty" if self.min_len == 1
                          else f"{_where(path)}: shorter than {self.min_len} characters")
        if self.max_len is not None and len(value) > self.max_len:
            errors.append(f"{_where(path)}: longer than {self.max_len} characters")
        if self.pattern and not re.fullmatch(self.pattern, value):
            errors.append(f"{_where(path)}: {value!r} is not {self.hint or 'valid'}")


@dataclass
class Int(Validator):
    min: int | None = None
    max: int | None = None

    def check(self, value: Any, path: str, errors: list[str]) -> None:
        if not isinstance(value, int) or isinstance(value, bool):
            errors.append(f"{_where(path)}: expected integer, got {_kind(value)}")
            return
        if self.min is not None and value < self.min:
            errors.append(f"{_where(path)}: {value} is less than {self.min}")
        if self.max is not None and value > self.max:
            errors.append(f"{_where(path)}: {value} is greater than {self.max}")


@dataclass
class Array(Validator):
    items: Validator
    min_len: int = 0

    def check(self, value: Any, path: str, errors: list[str]) -> None:
        if not isinstance(value, list):
            errors.append(f"{_where(path)}: expected array, got {_kind(value)}")
            return
        if len(value) < self.min_len:
            errors.append(f"{_where(path)}: needs at least {self.min_len} item(s)")
        for i, item in enumerate(value):
            self.items.check(item, f"{path}[{i}]", errors)


@dataclass
class Obj(Validator):
    fields: dict[str, Validator]
    optional: set[str] = field(default_factory=set)
    allow_extra: bool = False

    def check(self, value: Any, path: str, errors: list[str]) -> None:
        if not isinstance(value, dict):
            errors.append(f"{_where(path)}: expected object, got {_kind(value)}")
            return
        prefix = f"{path}." if path else ""
        for name, validator in self.fields.items():
            if name in value:
                validator.check(value[name], prefix + name, errors)
            elif name not in self.optional:
                errors.append(f"{prefix}{name}: required field is missing")
        if not self.allow_extra:
            for name in sorted(set(value) - set(self.fields)):
                errors.append(f"{prefix}{name}: unknown field")


SLUG = r"[a-z0-9]+(?:-[a-z0-9]+)*"
VERSION = r"\d+\.\d+\.\d+"
REQUIREMENT = r"(?:==|>=|<=|>|<|~=)?\d+(?:\.\d+){0,2}"

MANIFEST = Obj(
    {
        "id": Str(pattern=SLUG, max_len=64, hint="a lowercase id like 'better-maps'"),
        "name": Str(min_len=1, max_len=80),
        "version": Str(pattern=VERSION, hint="a version like '1.4.0'"),
        "game_version": Str(pattern=REQUIREMENT, hint="a requirement like '>=2.1'"),
        "authors": Array(Str(min_len=1), min_len=1),
        "dependencies": Array(Obj(
            {
                "id": Str(pattern=SLUG, hint="a lowercase id like 'core-lib'"),
                "version": Str(pattern=REQUIREMENT, hint="a requirement like '>=0.9'"),
            },
            optional={"version"},
        )),
        "load_order": Int(min=0, max=1000),
    },
    optional={"dependencies", "load_order"},
)


def validate_manifest(data: Any) -> list[str]:
    errors: list[str] = []
    MANIFEST.check(data, "", errors)
    return errors


def load_manifest(path: Path) -> dict[str, Any]:
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except json.JSONDecodeError as e:
        raise ValueError(f"{path}: invalid JSON at line {e.lineno}, column {e.colno}: {e.msg}") from None
    errors = validate_manifest(data)
    if errors:
        raise ValueError(f"{path}: {len(errors)} problem(s)\n" + "\n".join(f"  {e}" for e in errors))
    return data
```

