A recursive-descent parser fits this well: one method per precedence level, and each level calls the next tighter one. It evaluates while parsing, so no separate syntax tree is needed for a calculator.

Grammar, from loosest to tightest binding:

```
statement := NAME "=" expr | expr
expr      := term (("+" | "-") term)*
term      := unary (("*" | "/" | "%") unary)*
unary     := ("-" | "+") unary | power
power     := primary ("^" unary)?
primary   := NUMBER | NAME | NAME "(" [expr ("," expr)*] ")" | "(" expr ")"
```

```python
# calc.py
from __future__ import annotations

import math
import operator
from collections.abc import Callable

from lexer import LexError, Token, tokenize

FUNCTIONS: dict[str, Callable[..., float]] = {
    "sqrt": math.sqrt, "exp": math.exp, "log": math.log,
    "sin": math.sin, "cos": math.cos, "tan": math.tan,
    "abs": abs, "min": min, "max": max, "round": round,
}
BINARY = {"+": operator.add, "-": operator.sub, "*": operator.mul,
          "/": operator.truediv, "%": operator.mod}


class CalcError(Exception):
    def __init__(self, message: str, col: int) -> None:
        super().__init__(f"column {col}: {message}")
        self.col = col


class Parser:
    def __init__(self, tokens: list[Token], env: dict[str, float]) -> None:
        self.tokens = tokens
        self.i = 0
        self.env = env

    # --- token helpers
    @property
    def tok(self) -> Token:
        return self.tokens[self.i]

    def advance(self) -> Token:
        token = self.tokens[self.i]
        self.i += 1
        return token

    def at_op(self, ops: str) -> bool:
        return self.tok.kind == "OP" and self.tok.text in ops

    def expect(self, kind: str, what: str) -> Token:
        if self.tok.kind != kind:
            raise CalcError(f"expected {what}, got {self.tok.text or 'end of input'!r}", self.tok.col)
        return self.advance()

    # --- grammar
    def statement(self) -> float:
        if (self.tok.kind == "NAME" and self.i + 1 < len(self.tokens)
                and self.tokens[self.i + 1].text == "="):
            name = self.advance()
            self.advance()  # "="
            if name.text in FUNCTIONS:
                raise CalcError(f"cannot assign to function {name.text!r}", name.col)
            value = self.expr()
            self.env[name.text] = value
        else:
            value = self.expr()
        self.expect("EOF", "end of input")
        return value

    def expr(self) -> float:
        value = self.term()
        while self.at_op("+-"):
            op = self.advance()
            value = BINARY[op.text](value, self.term())
        return value

    def term(self) -> float:
        value = self.unary()
        while self.at_op("*/%"):
            op = self.advance()
            right = self.unary()
            if right == 0 and op.text in "/%":
                raise CalcError("division by zero", op.col)
            value = BINARY[op.text](value, right)
        return value

    def unary(self) -> float:
        if self.at_op("+-"):
            op = self.advance()
            value = self.unary()
            return -value if op.text == "-" else value
        return self.power()

    def power(self) -> float:
        base = self.primary()
        if self.at_op("^"):
            op = self.advance()
            exponent = self.unary()  # right-assoc: 2^3^2 = 2^(3^2); also allows 2^-1
            try:
                result = base ** exponent
            except OverflowError:
                raise CalcError("result too large", op.col) from None
            except ZeroDivisionError:
                raise CalcError("0 cannot be raised to a negative power", op.col) from None
            if isinstance(result, complex):
                raise CalcError("result is not a real number", op.col)
            return result
        return base

    def primary(self) -> float:
        token = self.tok
        if token.kind == "NUMBER":
            self.advance()
            return float(token.text)
        if token.kind == "NAME":
            self.advance()
            if self.tok.kind == "LPAREN":
                return self.call(token)
            if token.text not in self.env:
                raise CalcError(f"unknown variable {token.text!r}", token.col)
            return self.env[token.text]
        if token.kind == "LPAREN":
            self.advance()
            value = self.expr()
            self.expect("RPAREN", "')'")
            return value
        raise CalcError(f"unexpected {token.text or 'end of input'!r}", token.col)

    def call(self, name: Token) -> float:
        func = FUNCTIONS.get(name.text)
        if func is None:
            raise CalcError(f"unknown function {name.text!r}", name.col)
        self.expect("LPAREN", "'('")
        args: list[float] = []
        if self.tok.kind != "RPAREN":
            args.append(self.expr())
            while self.tok.kind == "COMMA":
                self.advance()
                args.append(self.expr())
        self.expect("RPAREN", "')'")
        try:
            return float(func(*args))
        except (TypeError, ValueError) as e:  # wrong argument count, sqrt(-1), ...
            raise CalcError(f"{name.text}(): {e}", name.col) from None


def evaluate(source: str, env: dict[str, float]) -> float:
    try:
        tokens = tokenize(source)
    except LexError as e:
        raise CalcError(str(e).split(": ", 1)[1], e.col) from None
    return Parser(tokens, env).statement()


def repl() -> None:
    env = {"pi": math.pi, "e": math.e}
    prompt = "calc> "
    while True:
        try:
            line = input(prompt)
        except (EOFError, KeyboardInterrupt):
            print()
            return
        if not line.strip():
            continue
        try:
            value = evaluate(line, env)
        except CalcError as e:
            print(" " * (len(prompt) + e.col - 1) + "^")
            print(f"error: {e}")
            continue
        print(int(value) if value.is_integer() else value)


if __name__ == "__main__":
    repl()
```

